/**
 * O ponto está DENTRO da cidade (em algum distrito)? Ray casting.
 *
 * É este teste que decide quem aparece no mapa e quem vira "fora de São Paulo"
 * no rodapé — errar aqui erra o número que a pessoa lê. A caixa do município
 * não serviria: Osasco cai dentro dela e fora da cidade.
 *
 * Como Marsilac e Parelheiros não estão na lista, quem mora lá conta como
 * fora. É consequência aceita da decisão de recortar o mapa: são áreas de
 * proteção ambiental, sem cliente.
 */
export function dentroDaCidade(lat: number, lng: number): boolean {
  for (let d = 0; d < ANEIS.length; d++) {
    const [laMin, lnMin, laMax, lnMax] = CAIXAS[d];
    if (lat < laMin || lat > laMax || lng < lnMin || lng > lnMax) continue;
    const p = ANEIS[d];
    let dentro = false;
    for (let i = 0, j = p.length - 1; i < p.length; j = i++) {
      if ((p[i][0] > lat) !== (p[j][0] > lat)
          && lng < ((p[j][1] - p[i][1]) * (lat - p[i][0])) / (p[j][0] - p[i][0]) + p[i][1]) {
        dentro = !dentro;
      }
    }
    if (dentro) return true;
  }
  return false;
}
